import type { RunDetail, RunInputs, ReviewResult, RunScope } from '../api.ts'
import { ReviewPanel } from '../ReviewDetail.tsx'
import { NodeSection } from '../SectionIndex.tsx'
import type { Resource } from '../useResource.ts'
import './review.css'

type DefinitionNode = RunDetail['definition']['nodes'][number]
type SnapshotNode = RunDetail['snapshot']['nodes'][number]

/** The independent review's section: the recorded verdict, its reviewers and their findings (docs/PRD_VIEWER_UX.md 4.7). */
export function ReviewSections({ scope, node, definitionNodes, snapshotNodes, inputs, refreshToken, onNavigate, onOpenRequirement, onOpenFile, onTransport }: {
  scope: RunScope
  node: SnapshotNode
  definitionNodes: DefinitionNode[]
  snapshotNodes: SnapshotNode[]
  inputs: Resource<RunInputs | null>
  refreshToken: number
  onNavigate: (pathname: string) => void
  onOpenRequirement: (nodeId: string, quote: string) => void
  onOpenFile: (nodeId: string, path: string) => void
  /** Called with the served review's transport, which decides the executor wording ("one print job per reviewer"). */
  onTransport: (transport: ReviewResult['reviewer']['transport']) => void
}) {
  return (
    <NodeSection sectionKey="review" title="Review result">
      <ReviewPanel
        scope={scope}
        node={node}
        definitionNodes={definitionNodes}
        snapshotNodes={snapshotNodes}
        inputs={inputs}
        refreshToken={refreshToken}
        onNavigate={onNavigate}
        onOpenRequirement={onOpenRequirement}
        onOpenFile={onOpenFile}
        onTransport={onTransport}
      />
    </NodeSection>
  )
}
import type { RunInputs } from '../api.ts'
import { ChallengePanel } from '../Challenge.tsx'
import { NodeSection } from '../SectionIndex.tsx'
import type { Resource } from '../useResource.ts'

/** The design challenge's section: its outcome, concerns, alternative and experiment, from the run inputs (docs/PRD_VIEWER_UX.md 4.8). */
export function ChallengeSections({ inputs, onRetryInputs }: { inputs: Resource<RunInputs | null>; onRetryInputs: () => void }) {
  return (
    <NodeSection sectionKey="challenge" title="Design challenge">
      <ChallengePanel inputs={inputs} onRetry={onRetryInputs} />
    </NodeSection>
  )
}
import type { ReactNode } from 'react'
import type { RunScope, WorkerResult, WorkflowEvent } from '../api.ts'
import { Time } from '../Time.tsx'
import { VerifiedEvidence } from './VerifySections.tsx'
import './controller.css'

/**
 * A step stopped at a decision nobody recorded yet: the approval requests of its events. Viewing approves nothing; the
 * decision is made in the workflow CLI.
 */
export function AwaitingNotice({ approvals }: { approvals: WorkflowEvent[] }) {
  return (
    <div className="projects-notice" role="status" data-testid="awaiting-notice">
      <p><strong>Awaiting approval.</strong> This node is stopped at a decision that has not been recorded. Viewing does not approve it; decisions are made through the workflow CLI.</p>
      {approvals.length > 0 && (
        <ul className="evidence-list">
          {approvals.map(event => <li key={event.event_id}>Requested at <Time iso={event.occurred_at} />: {event.message}</li>)}
        </ul>
      )}
    </div>
  )
}

/**
 * The controller's own steps (docs/PRD_VIEWER_UX.md 4.9): the freeze of the handoffs, the approval and the integration. One
 * panel with no index: what they recorded, which is usually no result of their own, and their History inline.
 */
export function ControllerSections({ scope, renderResult }: { scope: RunScope; renderResult: (evidence: (data: WorkerResult) => ReactNode) => ReactNode }) {
  return (
    <div className="controller-panel">
      {renderResult(data => <VerifiedEvidence scope={scope} result={data} phase="worker" />)}
    </div>
  )
}
/* ---- Review section (docs/PRD_VIEWER_UX.md 4.7); the review panel's own rules stay in App.css until S4c moves them. ---- */

.node-section .review-result { margin-top: 0; }
/* ---- The controller's steps: handoff, approval, integrate (docs/PRD_VIEWER_UX.md 4.9): one panel, no index ---- */

.controller-panel { margin-top: 8px; }

