/**
 * The fixture extension point of the viewer UX slices (docs/PRD_VIEWER_UX.md section 11). Each slice adds its runs in its
 * own module, `ux-<slice>.ts`, as a new workflow `ux-<slice>` appended after every workflow of `PROJECT`, so the existing
 * counts (two projects, five runs in `feature-flow`) do not change:
 * - `payloads`: the contract payloads the worker-phase mocks serve. This module spreads them into the maps `fixtures.ts`
 *   exports when it is first imported; `mock.ts` imports it, so they are merged before any request is served.
 * - `seed`: writes the same logical runs for the candidate phase and returns their registry entries; `seedCandidate`
 *   calls every module's seed with a `SeedContext`, appends the entries to `PROJECT`'s workflows and adds any top-level
 *   registry keys a module returns (S6's `viewer.expose_run_dir`, once the server accepts it).
 * After S1 no slice edits `fixtures.ts`, `mock.ts` or `seed.ts`: a slice changes only its own module. Modules import the
 * builders `fixtures.ts` exports and only types from here and from `seed.ts`, so no import cycle exists.
 */
import type { ReviewResult, RunDetail, RunInputs, WorkflowDefinition } from '../../../contracts/projects/v1.ts'
import type { WorkerResult, WorkflowEvent } from '../../../contracts/workflow/v1.ts'
import {
  artifactFiles, PROJECT, reviewResults, runDetails, runEvents, runInputs, runLists, workerResults, workflowLists,
  type ArtifactFile, type DefinitionNode,
} from '../fixtures.ts'
import type { SeedContext } from '../seed.ts'
import { uxLaunch } from './ux-launch.ts'
import { uxLists } from './ux-lists.ts'
import { uxNode } from './ux-node.ts'
import { uxReview } from './ux-review.ts'
import { uxRun } from './ux-run.ts'
import { uxTime } from './ux-time.ts'
import { uxVerify } from './ux-verify.ts'

/** A module's worker-phase payloads, keyed like the maps of `fixtures.ts`; run lists are derived from `runDetails`. */
export type UxPayloads = {
  /** Registered after every existing workflow of `PROJECT`, in module order. */
  workflows: WorkflowDefinition[]
  runDetails: Record<string, RunDetail>
  runEvents: Record<string, WorkflowEvent[]>
  /** Per run, keyed `<node>/<attempt>` or `candidate_<lane>/<attempt>` like the results route. */
  workerResults: Record<string, Record<string, WorkerResult>>
  reviewResults: Record<string, ReviewResult>
  runInputs: Record<string, RunInputs>
  artifactFiles: Record<string, ArtifactFile[]>
}

/** One registry workflow entry, as `seedCandidate` writes them. */
export type RegistryWorkflow = { workflow_id: string; runs_root: string; definition: { name: string; nodes: DefinitionNode[] } }

/** What a module's candidate-phase seed adds to the registry. */
export type UxSeed = {
  workflows: RegistryWorkflow[]
  /** Top-level registry keys beside `version` and `projects`; a later module's key replaces an earlier one's. */
  registry?: Record<string, unknown>
}

export type UxFixtureModule = {
  payloads?: Partial<UxPayloads>
  seed?: (context: SeedContext) => UxSeed
}

/** In slice order; the order the added workflows are listed in, in both phases. */
export const UX_FIXTURE_MODULES: readonly UxFixtureModule[] = [uxTime, uxRun, uxNode, uxVerify, uxLaunch, uxReview, uxLists]

function mergePayloads(modules: readonly UxFixtureModule[]) {
  for (const { payloads = {} } of modules) {
    const workflows = payloads.workflows ?? []
    workflowLists[PROJECT.project_id].workflows.push(...workflows)
    Object.assign(runDetails, payloads.runDetails)
    Object.assign(runEvents, payloads.runEvents)
    Object.assign(workerResults, payloads.workerResults)
    Object.assign(reviewResults, payloads.reviewResults)
    Object.assign(runInputs, payloads.runInputs)
    Object.assign(artifactFiles, payloads.artifactFiles)
    // The mocks index these per run: a run without events, results or artifacts serves none rather than failing.
    for (const runId of Object.keys(payloads.runDetails ?? {})) {
      runEvents[runId] ??= []
      workerResults[runId] ??= {}
      artifactFiles[runId] ??= []
    }
    // Each workflow's runs sorted by `updated_at` descending then `run_id` ascending, as the contract requires.
    for (const workflow of workflows) {
      runLists[workflow.workflow_id] = {
        runs: Object.values(runDetails).map(detail => detail.summary).filter(summary => summary.workflow_id === workflow.workflow_id)
          .sort((a, b) => b.updated_at.localeCompare(a.updated_at) || a.run_id.localeCompare(b.run_id)),
        next_cursor: null,
      }
    }
  }
}

mergePayloads(UX_FIXTURE_MODULES)

/** Seeds every module's runs for the candidate phase; returns what to add to the registry, in module order. */
export function seedUxFixtures(context: SeedContext): Required<UxSeed> {
  const seeded = UX_FIXTURE_MODULES.map(module => module.seed?.(context) ?? { workflows: [] })
  return {
    workflows: seeded.flatMap(seed => seed.workflows),
    registry: Object.assign({}, ...seeded.map(seed => seed.registry ?? {})) as Record<string, unknown>,
  }
}
/**
 * Fixtures of viewer UX slice S4c, review, challenge and controller nodes (`ux-review.spec.ts`) (docs/PRD_VIEWER_UX.md
 * 12.2), registered as the workflow `ux-review`: mock payloads for the worker phase and a `seed` for the candidate
 * phase, merged by `index.ts`. Empty until its slice adds them. S4c adds a native review with one running reviewer,
 * and a succeeded approval with no event.
 */
import type { UxFixtureModule } from './index.ts'

export const uxReview: UxFixtureModule = {}
/**
 * Helpers shared by the Projects viewer specs: URL builders, locators for the run view, the screenshot
 * attachment every scenario records, the per-test setup (isolated API up, mocks in worker mode) and the
 * redaction assertion used by the `paths-redacted` scenarios.
 */
import { test, expect, type APIRequestContext, type Locator, type Page, type TestInfo } from '@playwright/test'
import { waitForApi } from '../helpers.ts'
import { apiRunPath, PROJECT, WORKFLOW_ID } from './fixtures.ts'
import { verificationPhase } from './harness.ts'
import { installProjectMocks } from './mock.ts'

export const phase = verificationPhase()

export const projectsUrl = '/projects'
export const projectUrl = (projectId: string) => `/projects/${encodeURIComponent(projectId)}`
export const workflowUrl = (projectId: string, workflowId: string) => `${projectUrl(projectId)}/workflows/${encodeURIComponent(workflowId)}`
export const runUrl = (runId: string, nodeId?: string, workflowId: string = WORKFLOW_ID) => `${workflowUrl(PROJECT.project_id, workflowId)}/runs/${encodeURIComponent(runId)}${nodeId ? `/nodes/${encodeURIComponent(nodeId)}` : ''}`
export const apiRun = apiRunPath

export const workspace = (page: Page) => page.getByTestId('projects-workspace')
export const graphNode = (page: Page, nodeId: string) => page.locator(`[data-testid="workflow-graph"] [data-graph-node="${nodeId}"]`)
export const nodeListItem = (page: Page, nodeId: string) => page.locator(`[data-testid="run-node-list"] [data-node-id="${nodeId}"]`)
export const nodeDetail = (page: Page) => page.getByTestId('node-detail')
export const taskDetails = (page: Page) => page.getByTestId('task-details')

/** A launch node shows its task behind a disclosure, closed by default (PRD_VIEWER_CLARITY 4.2); this opens it. */
export async function openTask(page: Page) {
  await expect(taskDetails(page)).toBeVisible()
  if ((await taskDetails(page).getAttribute('open')) === null) await taskDetails(page).locator('summary').first().click()
  await expect(taskDetails(page)).toHaveAttribute('open', '')
}

/** No view action may launch, approve, retry, delete or edit a run: no such real controls exist (graph nodes are read-only selectors). */
export async function expectNoExecutionControls(page: Page) {
  const controls = workspace(page).locator('button, input, select, textarea, [role="menuitem"]')
  await expect(controls.filter({ hasText: /approve|retry|launch|start|resume|delete|cancel|integrate|edit|save/i })).toHaveCount(0)
  await expect(page.locator('form')).toHaveCount(0)
}

export async function attach(page: Page, testInfo: TestInfo, id: string) {
  const image = testInfo.outputPath(`${id}.png`)
  await page.screenshot({ path: image, fullPage: true })
  await testInfo.attach(`screenshot:${id}`, { path: image, contentType: 'image/png' })
}

export async function waitForProjectsApi(request: APIRequestContext) {
  if (phase !== 'candidate') return
  await expect.poll(async () => (await request.get('/api/projects')).status(), { timeout: 30_000 }).toBe(200)
}

/** Registers the suite's shared per-test setup; call once at the top level of a spec file. */
export function installHooks() {
  test.beforeEach(async ({ page, request }) => {
    await waitForApi(request)
    await waitForProjectsApi(request)
    if (phase === 'worker') await installProjectMocks(page)
  })
}

/** Reads the rendered text and asserts no absolute filesystem path (temporary root or home) leaked into it. */
export async function renderedText(locator: Locator): Promise<string> {
  const text = await locator.innerText()
  expect(text, 'rendered text must not name a temporary or home directory').not.toMatch(/\/tmp\/|\/home\//)
  return text
}

/** Fetches a URL from inside the page, so worker-mode route mocks apply exactly as they do for the app. */
export async function fetchFromPage(page: Page, url: string): Promise<{ status: number; contentType: string | null; text: string }> {
  return page.evaluate(async target => {
    const response = await fetch(target)
    return { status: response.status, contentType: response.headers.get('content-type'), text: await response.text() }
  }, url)
}
# Handoff: viewer UX slice S4a, verification and candidate pages (PRD_VIEWER_UX)

Implements row S4a of `docs/PRD_VIEWER_UX.md` section 11 (4.6, the Checks, Screenshots, Candidate lanes, Identifiers and Other-artifacts rows of 7, and 8) on branch `ux/s4a` (worktree `~/dev/mdm-ux-s4a`, from `feature/viewer-ux` after S4-core merged), 2026-09-24. S4b ran at the same time in another worktree; none of its files were touched. The first commit ran worker-phase checks only; the review-fix commit (section 7) ran the affected specs in both phases. The orchestrator runs the full suites.

## 1. What shipped

