/** A real absolute path under the run directory that the raw seeded texts name; the adapter must redact it. */
function leakFor(runsRoot: string, runId: string): string {
  return join(runsRoot, runId, 'worktree-ui', 'test-results')
}

const internalEvent = (sequence: number, time: string, node: string, status: string, message: string): InternalEvent => ({ sequence, time, node, status, message })

/** What a viewer UX fixture module gets to write its runs in the documented storage format (`fixtures/index.ts`). */
export type SeedContext = {
  /** The shared repository every seeded project points at. */
  repository: string
  /** Creates and returns the runs root of one workflow, `<root>/runs/<workflow id>`. */
  runsRoot: (workflowId: string) => string
  writeRun: typeof writeRun
  writePacket: typeof writePacket
  receipt: typeof receipt
  internalEvent: typeof internalEvent
  leakFor: typeof leakFor
}

/** Seeds registry + runs under `root`; returns the registry path for MD_MANAGER_PROJECTS_CONFIG. */
export function seedCandidate(root: string): string {
  const repository = join(root, 'repository')
  const runsRoot = join(root, 'runs', WORKFLOW_ID)
  const emptyRunsRoot = join(root, 'runs', EMPTY_WORKFLOW_ID)
  const lanesRunsRoot = join(root, 'runs', LANES_WORKFLOW_ID)
  const reviewersRunsRoot = join(root, 'runs', REVIEWERS_WORKFLOW_ID)
  const clarityRunsRoot = join(root, 'runs', CLARITY_WORKFLOW_ID)
  const guardedRunsRoot = join(root, 'runs', GUARDED_WORKFLOW_ID)
  mkdirSync(repository, { recursive: true })
  mkdirSync(runsRoot, { recursive: true })
  mkdirSync(emptyRunsRoot, { recursive: true })
  mkdirSync(lanesRunsRoot, { recursive: true })
  mkdirSync(reviewersRunsRoot, { recursive: true })
  mkdirSync(clarityRunsRoot, { recursive: true })
  mkdirSync(guardedRunsRoot, { recursive: true })

  const packetSet = (runDir: string, phases: { phase: 'worker' | 'candidate'; node: string; attempt: number; result: WorkerResult; blocked?: string }[]) =>
    phases.map(entry => writePacket(runDir, entry.phase, entry.node, entry.attempt, entry.result, LANE_ARTIFACTS[entry.node],
      entry.blocked ? { status: 'blocked', reasons: [entry.blocked] }
        // Seeded evidence receipts are `check-<index>`, so a deferred check is named by its executed index.
        : { status: 'passed', reasons: [], ...(entry.result.deferred_checks ? { deferred_checks: entry.result.deferred_checks.map(check => `check-${check.check_index}`) } : {}) }))
  const fullPackets = (runId: string, runDir: string) => packetSet(runDir, [
    { phase: 'worker', node: 'ui', attempt: 1, result: uiResult(runId) },
    { phase: 'worker', node: 'adapter', attempt: 1, result: adapterResult(runId, false) },
    { phase: 'candidate', node: 'ui', attempt: 1, result: uiResult(runId) },
    { phase: 'candidate', node: 'adapter', attempt: 1, result: adapterResult(runId, false) },
  ])
  const reviewedValues = (runId: string, requestedAt: string) => ({
    ui: receipt('ui', join(runsRoot, runId), UI_SESSION, requestedAt), adapter: receipt('adapter', join(runsRoot, runId), ADAPTER_SESSION, requestedAt),
    snapshots: { ui: OUTPUT_COMMIT_UI, adapter: OUTPUT_COMMIT_ADAPTER },
    ui_packet: 'verification/worker/ui/1/packet.json', adapter_packet: 'verification/worker/adapter/1/packet.json',
    bundle: { run_id: runId, base_commit: BASE_COMMIT, candidate_commit: CANDIDATE_COMMIT, policy_sha256: 'e'.repeat(64) },
  })
  const launchEvents = (time: string) => [
    internalEvent(1, time, 'ui', 'running', 'Launching or reconciling the exact native session'),
    internalEvent(2, time, 'adapter', 'running', 'Launching or reconciling the exact native session'),
  ]

  writeRun(runsRoot, repository, RUN_SUCCEEDED, {
    createdAt: T0, updatedAt: T3, definitionNodes: PINNED_NODES,
    values: {
      ...reviewedValues(RUN_SUCCEEDED, T0),
      review: { run_id: RUN_SUCCEEDED, verdict: 'approved', independent: true, reviewer: 'synthetic-reviewer', findings: [] },
      approved_bundle: 'f'.repeat(64), integrated_commit: CANDIDATE_COMMIT,
    },
    next: [], tasks: [],
    events: [
      ...launchEvents(T0),
      internalEvent(3, T1, 'freeze', 'succeeded', 'Captured both worker snapshots'),
      internalEvent(4, T2, 'verify_ui', 'succeeded', 'UI verification passed'),
      internalEvent(5, T2, 'verify_adapter', 'succeeded', 'Adapter verification passed'),
      internalEvent(6, T3, 'review', 'approved', 'Independent reviewer approved the candidate'),
      internalEvent(7, T3, 'integrate', 'succeeded', 'Fast-forwarded the feature branch'),
    ],
    packets: runDir => fullPackets(RUN_SUCCEEDED, runDir),
    review: rawReviewSection(RUN_SUCCEEDED, leakFor(runsRoot, RUN_SUCCEEDED)),
    inputs: rawInputsSection(RUN_SUCCEEDED, leakFor(runsRoot, RUN_SUCCEEDED)),
    diff: REVIEW_DIFF,
  })

  writeRun(runsRoot, repository, RUN_FAILED, {
    createdAt: T1, updatedAt: T2, definitionNodes: GRAPH_NODES,
    values: {
      ui: receipt('ui', join(runsRoot, RUN_FAILED), UI_SESSION, T1), adapter: receipt('adapter', join(runsRoot, RUN_FAILED), ADAPTER_SESSION, T1),
      snapshots: { ui: OUTPUT_COMMIT_UI, adapter: OUTPUT_COMMIT_ADAPTER },
      ui_packet: 'verification/worker/ui/1/packet.json',
    },
    next: ['verify_adapter'],
    tasks: [{ node_id: 'verify_adapter', error: 'Injected gate failure: adapter verification attempt 1 was blocked by the configured failure drill', interrupts: [], result: null }],
    events: [
      ...launchEvents(T1),
      internalEvent(3, T2, 'freeze', 'succeeded', 'Captured both worker snapshots'),
      internalEvent(4, T2, 'verify_ui', 'succeeded', 'UI verification passed'),
      internalEvent(5, T2, 'verify_adapter', 'failed', 'Injected gate failure (failure drill); checks preserved'),
    ],
    packets: runDir => packetSet(runDir, [
      { phase: 'worker', node: 'ui', attempt: 1, result: uiResult(RUN_FAILED) },
      { phase: 'worker', node: 'adapter', attempt: 1, result: adapterResult(RUN_FAILED, true), blocked: 'Injected gate failure (failure drill)' },
    ]),
    review: null,
    inputs: rawInputsSection(RUN_FAILED, leakFor(runsRoot, RUN_FAILED)),
  })

  writeRun(runsRoot, repository, RUN_AWAITING, {
    createdAt: T2, updatedAt: T3, definitionNodes: GRAPH_NODES,
    values: reviewedValues(RUN_AWAITING, T2),
    next: ['review'],
    tasks: [{ node_id: 'review', error: null, interrupts: [{ kind: 'independent_review', message: 'Independent review required before integration' }], result: null }],
    events: [
      ...launchEvents(T2),
      internalEvent(3, T3, 'freeze', 'succeeded', 'Captured both worker snapshots'),
      internalEvent(4, T3, 'candidate', 'succeeded', 'Combined candidate checks passed'),
      internalEvent(5, T3, 'review', 'awaiting_approval', 'Independent review required before integration'),
    ],
    packets: runDir => fullPackets(RUN_AWAITING, runDir),
    review: null,
    inputs: rawInputsSection(RUN_AWAITING, leakFor(runsRoot, RUN_AWAITING)),
  })

  // The print-mode reviewer blocked this candidate: review.json holds the verdict, the graph task the error.
  writeRun(runsRoot, repository, RUN_BLOCKED, {
    createdAt: T1, updatedAt: T3, definitionNodes: GRAPH_NODES,
    values: reviewedValues(RUN_BLOCKED, T1),
    next: [],
    tasks: [{ node_id: 'review', error: `${BLOCKED_MESSAGE}; see ${join(runsRoot, RUN_BLOCKED, 'review.json')}`, interrupts: [], result: null }],
    events: [
      ...launchEvents(T1),
      internalEvent(3, T2, 'freeze', 'succeeded', 'Captured both worker snapshots'),
      internalEvent(4, T2, 'verify_ui', 'succeeded', 'UI verification passed'),
      internalEvent(5, T2, 'verify_adapter', 'succeeded', 'Adapter verification passed'),
      internalEvent(6, T2, 'candidate', 'succeeded', 'Combined candidate checks passed'),
      internalEvent(7, T3, 'review', 'running', 'Launching the print-mode reviewer'),
      internalEvent(8, T3, 'review', 'blocked', BLOCKED_MESSAGE),
    ],
    packets: runDir => packetSet(runDir, [
      { phase: 'worker', node: 'ui', attempt: 1, result: uiDeferredResult(RUN_BLOCKED) },
      { phase: 'worker', node: 'adapter', attempt: 1, result: adapterResult(RUN_BLOCKED, false) },
      { phase: 'candidate', node: 'ui', attempt: 1, result: uiResult(RUN_BLOCKED) },
      { phase: 'candidate', node: 'adapter', attempt: 1, result: adapterResult(RUN_BLOCKED, false) },
    ]),
    review: rawReviewSection(RUN_BLOCKED, leakFor(runsRoot, RUN_BLOCKED)),
    inputs: rawInputsSection(RUN_BLOCKED, leakFor(runsRoot, RUN_BLOCKED)),
  })

  // Integrated before review results and run inputs were exported: a 1.0.0 export whose `values.review` is never mined.
  writeRun(runsRoot, repository, RUN_LEGACY, {
    createdAt: T0, updatedAt: T2, definitionNodes: GRAPH_NODES,
    values: {
      ...reviewedValues(RUN_LEGACY, T0),
      review: { run_id: RUN_LEGACY, verdict: 'approved', independent: true, reviewer: 'synthetic-reviewer', findings: [] },
      approved_bundle: 'f'.repeat(64), integrated_commit: CANDIDATE_COMMIT,
    },
    next: [], tasks: [],
    events: [
      ...launchEvents(T0),
      internalEvent(3, T1, 'freeze', 'succeeded', 'Captured both worker snapshots'),
      internalEvent(4, T1, 'verify_ui', 'succeeded', 'UI verification passed'),
      internalEvent(5, T1, 'verify_adapter', 'succeeded', 'Adapter verification passed'),
      internalEvent(6, T2, 'review', 'approved', 'Review accepted (recorded before review results were exported)'),
      internalEvent(7, T2, 'integrate', 'succeeded', 'Fast-forwarded the feature branch'),
    ],
    packets: runDir => fullPackets(RUN_LEGACY, runDir),
    version: '1.0.0',
  })

  // ---- lanes-flow: 1.3.0 exports of runs whose lanes come from configuration (`ui`, `adapter`, `docs`) ----

  /** Per-lane state as the plan-driven pipeline keeps it, up to the verified candidate: receipts under `lanes`, packet paths under `packets`. */
  const laneCandidateValues = (runsRoot: string, runId: string, lanes: readonly string[], requestedAt: string) => ({
    lanes: Object.fromEntries(lanes.map(lane => [lane, receipt(lane, join(runsRoot, runId), LANE_SESSIONS[lane], requestedAt)])),
    snapshots: Object.fromEntries(lanes.map(lane => [lane, LANE_OUTPUT_COMMITS[lane]])),
    packets: Object.fromEntries(lanes.map(lane => [lane, `verification/worker/${lane}/1/packet.json`])),
    bundle: { run_id: runId, base_commit: BASE_COMMIT, candidate_commit: CANDIDATE_COMMIT, policy_sha256: 'e'.repeat(64) },
  })
  /** A configured run that was reviewed, approved and integrated. */
  const laneValues = (runId: string, lanes: readonly string[], requestedAt: string, runsRoot = lanesRunsRoot) => ({
    ...laneCandidateValues(runsRoot, runId, lanes, requestedAt),
    review: { run_id: runId, verdict: 'approved', independent: true, reviewer: 'synthetic-reviewer', findings: [] },
    approved_bundle: 'f'.repeat(64), integrated_commit: CANDIDATE_COMMIT,
  })
  const lanePackets = (runId: string, runDir: string, lanes: readonly string[]) => packetSet(runDir, lanes.flatMap(lane => [
    { phase: 'worker' as const, node: lane, attempt: 1, result: laneResult(lane, runId) },
    { phase: 'candidate' as const, node: lane, attempt: 1, result: laneResult(lane, runId) },
  ]))
  const laneEvents = (lanes: readonly string[], start: string, extra: InternalEvent[] = []): InternalEvent[] => {
    const events: InternalEvent[] = []
    const push = (time: string, node: string, status: string, message: string) => events.push(internalEvent(events.length + 1, time, node, status, message))
    for (const lane of lanes) push(start, lane, 'running', 'Launching or reconciling the exact native session')
    for (const event of extra) push(event.time, event.node, event.status, event.message)
    push(T2, 'freeze', 'succeeded', `Captured ${lanes.length === 1 ? 'the' : 'every'} worker snapshot`)
    for (const lane of lanes) push(T2, `verify_${lane}`, 'succeeded', `${lane} verification passed`)
    push(T2, 'candidate', 'succeeded', 'Combined candidate checks passed')
    push(T3, 'review', 'approved', 'Independent reviewer approved the candidate')
    push(T3, 'integrate', 'succeeded', 'Fast-forwarded the feature branch')
    return events
  }

  writeRun(lanesRunsRoot, repository, RUN_THREE_LANES, {
    createdAt: T1, updatedAt: T3, definitionNodes: THREE_LANE_NODES, definitionName: LANES_WORKFLOW_NAME, version: '1.3.0', lanes: THREE_LANES,
    values: laneValues(RUN_THREE_LANES, THREE_LANES, T1),
    next: [], tasks: [],
    events: laneEvents(THREE_LANES, T1),
    packets: runDir => lanePackets(RUN_THREE_LANES, runDir, THREE_LANES),
    review: rawReviewSection(RUN_THREE_LANES, leakFor(lanesRunsRoot, RUN_THREE_LANES)),
    inputs: rawInputsSection(RUN_THREE_LANES, leakFor(lanesRunsRoot, RUN_THREE_LANES)),
  })

  // Launched with `--workers docs`: the plan pins one lane and excludes the other two; the drill's lane was not selected.
  writeRun(lanesRunsRoot, repository, RUN_ONE_LANE, {
    createdAt: T2, updatedAt: T3, definitionNodes: ONE_LANE_NODES, definitionName: LANES_WORKFLOW_NAME, version: '1.3.0', lanes: ONE_LANE,
    values: laneValues(RUN_ONE_LANE, ONE_LANE, T2),
    next: [], tasks: [],
    events: laneEvents(ONE_LANE, T2, [internalEvent(0, T2, 'failure_drill', 'skipped', 'Failure drill skipped: its lane adapter was not selected')]),
    packets: runDir => lanePackets(RUN_ONE_LANE, runDir, ONE_LANE),
    review: rawReviewSection(RUN_ONE_LANE, leakFor(lanesRunsRoot, RUN_ONE_LANE)),
    inputs: rawInputsSection(RUN_ONE_LANE, leakFor(lanesRunsRoot, RUN_ONE_LANE)),
  })

  // ---- reviewers-flow: a feature declaring the reviewers `general` and `coverage` over the plain two-lane graph ----

  const reviewersLeak = (runId: string) => leakFor(reviewersRunsRoot, runId)
  const reviewerLaunchEvents = (): InternalEvent[] => [
    internalEvent(0, T2, 'review', 'running', 'Launching reviewer general over the shared review worktree'),
    internalEvent(0, T2, 'review', 'running', 'Launching reviewer coverage over the shared review worktree'),
  ]

  // Both reviewers' completion files were accepted: review.json holds the combined verdict and both entries.
  writeRun(reviewersRunsRoot, repository, RUN_TWO_REVIEWERS, {
    createdAt: T1, updatedAt: T3, definitionNodes: REVIEWERS_NODES, definitionName: REVIEWERS_WORKFLOW_NAME, version: '1.4.0', lanes: TWO_LANES, reviewers: TWO_REVIEWERS,
    values: {
      ...laneValues(RUN_TWO_REVIEWERS, TWO_LANES, T1, reviewersRunsRoot),
      review: {
        run_id: RUN_TWO_REVIEWERS, verdict: 'approved', independent: true, reviewer: 'synthetic-reviewer', findings: [],
        reviewers: TWO_REVIEWERS.map(reviewer => ({ reviewer_id: reviewer, session_id: `synthetic-${reviewer}`, verdict: 'approved', accepted_at: T3 })),
      },
    },
    next: [], tasks: [],
    events: laneEvents(TWO_LANES, T1, reviewerLaunchEvents()),
    packets: runDir => lanePackets(RUN_TWO_REVIEWERS, runDir, TWO_LANES),
    review: rawReviewSection(RUN_TWO_REVIEWERS, reviewersLeak(RUN_TWO_REVIEWERS)),
    inputs: rawInputsSection(RUN_TWO_REVIEWERS, reviewersLeak(RUN_TWO_REVIEWERS)),
  })

  // `coverage` blocked while `general` was still working: the run failed at the review node and `general` was stopped and superseded.
  writeRun(reviewersRunsRoot, repository, RUN_REVIEWER_BLOCKED, {
    createdAt: T2, updatedAt: T3, definitionNodes: REVIEWERS_NODES, definitionName: REVIEWERS_WORKFLOW_NAME, version: '1.4.0', lanes: TWO_LANES, reviewers: TWO_REVIEWERS,
    values: laneCandidateValues(reviewersRunsRoot, RUN_REVIEWER_BLOCKED, TWO_LANES, T2),
    next: [],
    tasks: [{ node_id: 'review', error: `${REVIEWER_BLOCKED_MESSAGE}; see ${join(reviewersRunsRoot, RUN_REVIEWER_BLOCKED, 'review.json')}`, interrupts: [], result: null }],
    events: (() => {
      const events: InternalEvent[] = []
      const push = (time: string, node: string, status: string, message: string) => events.push(internalEvent(events.length + 1, time, node, status, message))
      for (const lane of TWO_LANES) push(T2, lane, 'running', 'Launching or reconciling the exact native session')
      push(T2, 'freeze', 'succeeded', 'Captured every worker snapshot')
      for (const lane of TWO_LANES) push(T2, `verify_${lane}`, 'succeeded', `${lane} verification passed`)
      push(T2, 'candidate', 'succeeded', 'Combined candidate checks passed')
      for (const event of reviewerLaunchEvents()) push(event.time, event.node, event.status, event.message)
      push(T3, 'review', 'blocked', REVIEWER_BLOCKED_MESSAGE)
      return events
    })(),
    packets: runDir => lanePackets(RUN_REVIEWER_BLOCKED, runDir, TWO_LANES),
    review: rawReviewSection(RUN_REVIEWER_BLOCKED, reviewersLeak(RUN_REVIEWER_BLOCKED)),
    inputs: rawInputsSection(RUN_REVIEWER_BLOCKED, reviewersLeak(RUN_REVIEWER_BLOCKED)),
  })

  // Reviewed before the feature declared reviewers: a 1.3.0 export whose review section has no `reviewers` list.
  writeRun(reviewersRunsRoot, repository, RUN_LEGACY_REVIEWER, {
    createdAt: T0, updatedAt: T2, definitionNodes: REVIEWERS_NODES, definitionName: REVIEWERS_WORKFLOW_NAME, version: '1.3.0', lanes: TWO_LANES,
    values: laneValues(RUN_LEGACY_REVIEWER, TWO_LANES, T0, reviewersRunsRoot),
    next: [], tasks: [],
    events: laneEvents(TWO_LANES, T0),
    packets: runDir => lanePackets(RUN_LEGACY_REVIEWER, runDir, TWO_LANES),
    review: rawReviewSection(RUN_LEGACY_REVIEWER, reviewersLeak(RUN_LEGACY_REVIEWER)),
    inputs: rawInputsSection(RUN_LEGACY_REVIEWER, reviewersLeak(RUN_LEGACY_REVIEWER)),
  })

  // ---- clarity-flow: the ui worker-phase packet captured the changed files at freeze (PRD_VIEWER_CLARITY 4.1) ----

  writeRun(clarityRunsRoot, repository, RUN_FILES, {
    createdAt: T1, updatedAt: T3, definitionNodes: CLARITY_NODES, definitionName: CLARITY_WORKFLOW_NAME, version: '1.4.0', lanes: TWO_LANES, reviewers: TWO_REVIEWERS,
    values: laneValues(RUN_FILES, TWO_LANES, T1, clarityRunsRoot),
    next: [], tasks: [],
    events: laneEvents(TWO_LANES, T1, reviewerLaunchEvents()),
    packets: runDir => [
      writePacket(runDir, 'worker', 'ui', 1, capturedUiResult(RUN_FILES), [...LANE_ARTIFACTS.ui, ...FILE_ARTIFACTS], { status: 'passed', reasons: [] }),
      writePacket(runDir, 'worker', 'adapter', 1, adapterResult(RUN_FILES, false), LANE_ARTIFACTS.adapter, { status: 'passed', reasons: [] }),
      writePacket(runDir, 'candidate', 'ui', 1, candidateUiResult(RUN_FILES), LANE_ARTIFACTS.ui, { status: 'passed', reasons: [] }),
      writePacket(runDir, 'candidate', 'adapter', 1, adapterResult(RUN_FILES, false), LANE_ARTIFACTS.adapter, { status: 'passed', reasons: [] }),
    ],
    review: rawReviewSection(RUN_FILES, leakFor(clarityRunsRoot, RUN_FILES)),
    inputs: rawInputsSection(RUN_FILES, leakFor(clarityRunsRoot, RUN_FILES)),
  })

  // ---- guarded-flow: 1.5.0 exports whose graph starts with the design challenge (PRD_PORTABLE_WORKFLOW 4.5 to 4.7) ----

  // Finished: the challenge was accepted at attempt 2, both lanes verified (ui captured a Markdown file), the print reviewer
  // approved at attempt 1 with a finding naming that file, and the candidate was integrated.
  writeRun(guardedRunsRoot, repository, RUN_GUARDED, {
    createdAt: T1, updatedAt: T3, definitionNodes: GUARDED_NODES, definitionName: GUARDED_WORKFLOW_NAME, version: '1.5.0', lanes: TWO_LANES,
    values: laneValues(RUN_GUARDED, TWO_LANES, T1, guardedRunsRoot),
    next: [], tasks: [],
    events: [
      internalEvent(1, T1, 'challenge', 'succeeded', `Design challenge attempt 2 accepted by the operator: ${CHALLENGE_ACCEPTED_REASON}`),
      internalEvent(2, T1, 'ui', 'running', 'Launching or reconciling the exact native session'),
      internalEvent(3, T1, 'adapter', 'running', 'Launching or reconciling the exact native session'),
      internalEvent(4, T2, 'freeze', 'succeeded', 'Captured every worker snapshot'),
      internalEvent(5, T2, 'verify_ui', 'succeeded', 'ui verification passed; changed text files captured at freeze'),
      internalEvent(6, T2, 'verify_adapter', 'succeeded', 'adapter verification passed'),
      internalEvent(7, T2, 'candidate', 'succeeded', 'Combined candidate checks passed'),
      internalEvent(8, T3, 'review', 'approved', 'Independent reviewer approved the candidate'),
      internalEvent(9, T3, 'integrate', 'succeeded', 'Fast-forwarded the feature branch'),
    ],
    packets: runDir => [
      writePacket(runDir, 'worker', 'ui', 1, guardedUiResult(RUN_GUARDED), [...LANE_ARTIFACTS.ui, ...GUARDED_FILE_ARTIFACTS], { status: 'passed', reasons: [] }),
      writePacket(runDir, 'worker', 'adapter', 1, adapterResult(RUN_GUARDED, false), LANE_ARTIFACTS.adapter, { status: 'passed', reasons: [] }),
      writePacket(runDir, 'candidate', 'ui', 1, uiResult(RUN_GUARDED), LANE_ARTIFACTS.ui, { status: 'passed', reasons: [] }),
      writePacket(runDir, 'candidate', 'adapter', 1, adapterResult(RUN_GUARDED, false), LANE_ARTIFACTS.adapter, { status: 'passed', reasons: [] }),
    ],
    review: rawReviewSection(RUN_GUARDED, leakFor(guardedRunsRoot, RUN_GUARDED)),
    inputs: rawInputsSection(RUN_GUARDED, leakFor(guardedRunsRoot, RUN_GUARDED)),
  })

  /** Both sessions launched and the automatic run waits at the handoff interrupt: nothing is frozen or verified yet. */
  const awaitingHandoffs = (runId: string) => ({
    values: { lanes: Object.fromEntries(TWO_LANES.map(lane => [lane, receipt(lane, join(guardedRunsRoot, runId), LANE_SESSIONS[lane], T1)])) },
    next: ['handoff'],
    tasks: [{ node_id: 'handoff', error: null, interrupts: [{ kind: 'worker_handoff', message: 'Awaiting explicit completion signals and automatic freeze.' }], result: null }],
  })
  const guardedLaunchEvents = [
    internalEvent(1, T1, 'challenge', 'succeeded', 'Design challenge attempt 1 passed (1 P2 concern(s)); launching workers'),
    internalEvent(2, T1, 'ui', 'running', 'Launching or reconciling the exact native session'),
    internalEvent(3, T1, 'adapter', 'running', 'Launching or reconciling the exact native session'),
  ]

  // Waiting on handoffs: ui finished its turn; the adapter's second question waits on the operator (its file was moved).
  const askingDir = join(guardedRunsRoot, RUN_GUARDED_ASKING)
  writeRun(guardedRunsRoot, repository, RUN_GUARDED_ASKING, {
    createdAt: T1, updatedAt: T3, definitionNodes: GUARDED_NODES, definitionName: GUARDED_WORKFLOW_NAME, version: '1.5.0', lanes: TWO_LANES,
    ...awaitingHandoffs(RUN_GUARDED_ASKING),
    events: [
      ...guardedLaunchEvents,
      internalEvent(4, T2, 'adapter', 'interactive', `Worker adapter asked question 1 of 3; its deadline is paused until \`python -m workflow answer ${askingDir} adapter "<text>"\`: ${GUARDED_QUESTIONS.adapter[0].question}`),
      internalEvent(5, T2, 'adapter', 'interactive', 'Worker adapter question 1 answered; its deadline runs again'),
      internalEvent(6, T3, 'adapter', 'interactive', `Worker adapter asked question 2 of 3; its deadline is paused until \`python -m workflow answer ${askingDir} adapter "<text>"\`: ${GUARDED_QUESTIONS.adapter[1].question}`),
    ],
    packets: () => [],
    review: null,
    inputs: rawInputsSection(RUN_GUARDED_ASKING, leakFor(guardedRunsRoot, RUN_GUARDED_ASKING)),
  })

  // Blocked in the same wait: the ui worker asked a fourth question, which the controller refused, and it stopped both workers.
  writeRun(guardedRunsRoot, repository, RUN_GUARDED_BLOCKED, {
    createdAt: T1, updatedAt: T3, definitionNodes: GUARDED_NODES, definitionName: GUARDED_WORKFLOW_NAME, version: '1.5.0', lanes: TWO_LANES,
    ...awaitingHandoffs(RUN_GUARDED_BLOCKED),
    events: [
      ...guardedLaunchEvents,
      internalEvent(4, T2, 'ui', 'interactive', 'Worker ui question 3 answered; its deadline runs again'),
      internalEvent(5, T3, 'controller', 'blocked', FOURTH_QUESTION_MESSAGE),
    ],
    packets: () => [],
    review: null,
    inputs: rawInputsSection(RUN_GUARDED_BLOCKED, leakFor(guardedRunsRoot, RUN_GUARDED_BLOCKED)),
  })

  // ---- viewer UX slices: each module seeds its own workflow, appended after every workflow above ----

  const ux = seedUxFixtures({
    repository,
    runsRoot: workflowId => {
      const directory = join(root, 'runs', workflowId)
      mkdirSync(directory, { recursive: true })
      return directory
    },
    writeRun, writePacket, receipt, internalEvent, leakFor,
  })

  const registry = {
    version: 1,
    ...ux.registry,
    projects: [
      {
        project_id: PROJECT.project_id, name: PROJECT.name, repository,
        workflows: [
          { workflow_id: WORKFLOW_ID, runs_root: runsRoot, definition: { name: WORKFLOW_NAME, nodes: GRAPH_NODES } },
          { workflow_id: EMPTY_WORKFLOW_ID, runs_root: emptyRunsRoot, definition: { name: EMPTY_WORKFLOW_NAME, nodes: EMPTY_WORKFLOW_DEFINITION.nodes } },
          { workflow_id: LANES_WORKFLOW_ID, runs_root: lanesRunsRoot, definition: { name: LANES_WORKFLOW_NAME, nodes: THREE_LANE_NODES } },
          { workflow_id: REVIEWERS_WORKFLOW_ID, runs_root: reviewersRunsRoot, definition: { name: REVIEWERS_WORKFLOW_NAME, nodes: REVIEWERS_NODES } },
          { workflow_id: CLARITY_WORKFLOW_ID, runs_root: clarityRunsRoot, definition: { name: CLARITY_WORKFLOW_NAME, nodes: CLARITY_NODES } },
          { workflow_id: GUARDED_WORKFLOW_ID, runs_root: guardedRunsRoot, definition: { name: GUARDED_WORKFLOW_NAME, nodes: GUARDED_NODES } },
          ...ux.workflows,
        ],
      },
      { project_id: EMPTY_PROJECT.project_id, name: EMPTY_PROJECT.name, repository, workflows: [] },
    ],
  }
  const configPath = join(root, 'projects.json')
  writeJson(configPath, registry)
  return configPath
}

toolUseResult.stdout:
  }
  writeJson(join(runDir, 'run-state.json'), state)
  return runDir
}

/** A real absolute path under the run directory that the raw seeded texts name; the adapter must redact it. */
function leakFor(runsRoot: string, runId: string): string {
  return join(runsRoot, runId, 'worktree-ui', 'test-results')
}

const internalEvent = (sequence: number, time: string, node: string, status: string, message: string): InternalEvent => ({ sequence, time, node, status, message })

/** What a viewer UX fixture module gets to write its runs in the documented storage format (`fixtures/index.ts`). */
export type SeedContext = {
  /** The shared repository every seeded project points at. */
  repository: string
  /** Creates and returns the runs root of one workflow, `<root>/runs/<workflow id>`. */
  runsRoot: (workflowId: string) => string
  writeRun: typeof writeRun
  writePacket: typeof writePacket
  receipt: typeof receipt
  internalEvent: typeof internalEvent
  leakFor: typeof leakFor
}

/** Seeds registry + runs under `root`; returns the registry path for MD_MANAGER_PROJECTS_CONFIG. */
export function seedCandidate(root: string): string {
  const repository = join(root, 'repository')
  const runsRoot = join(root, 'runs', WORKFLOW_ID)
  const emptyRunsRoot = join(root, 'runs', EMPTY_WORKFLOW_ID)
  const lanesRunsRoot = join(root, 'runs', LANES_WORKFLOW_ID)
  const reviewersRunsRoot = join(root, 'runs', REVIEWERS_WORKFLOW_ID)
  const clarityRunsRoot = join(root, 'runs', CLARITY_WORKFLOW_ID)
  const guardedRunsRoot = join(root, 'runs', GUARDED_WORKFLOW_ID)
  mkdirSync(repository, { recursive: true })
  mkdirSync(runsRoot, { recursive: true })
  mkdirSync(emptyRunsRoot, { recursive: true })
  mkdirSync(lanesRunsRoot, { recursive: true })
  mkdirSync(reviewersRunsRoot, { recursive: true })
  mkdirSync(clarityRunsRoot, { recursive: true })
  mkdirSync(guardedRunsRoot, { recursive: true })

  const packetSet = (runDir: string, phases: { phase: 'worker' | 'candidate'; node: string; attempt: number; result: WorkerResult; blocked?: string }[]) =>
    phases.map(entry => writePacket(runDir, entry.phase, entry.node, entry.attempt, entry.result, LANE_ARTIFACTS[entry.node],
      entry.blocked ? { status: 'blocked', reasons: [entry.blocked] }
        // Seeded evidence receipts are `check-<index>`, so a deferred check is named by its executed index.
        : { status: 'passed', reasons: [], ...(entry.result.deferred_checks ? { deferred_checks: entry.result.deferred_checks.map(check => `check-${check.check_index}`) } : {}) }))
  const fullPackets = (runId: string, runDir: string) => packetSet(runDir, [
    { phase: 'worker', node: 'ui', attempt: 1, result: uiResult(runId) },
    { phase: 'worker', node: 'adapter', attempt: 1, result: adapterResult(runId, false) },
    { phase: 'candidate', node: 'ui', attempt: 1, result: uiResult(runId) },
    { phase: 'candidate', node: 'adapter', attempt: 1, result: adapterResult(runId, false) },
  ])
  const reviewedValues = (runId: string, requestedAt: string) => ({
    ui: receipt('ui', join(runsRoot, runId), UI_SESSION, requestedAt), adapter: receipt('adapter', join(runsRoot, runId), ADAPTER_SESSION, requestedAt),
    snapshots: { ui: OUTPUT_COMMIT_UI, adapter: OUTPUT_COMMIT_ADAPTER },
    ui_packet: 'verification/worker/ui/1/packet.json', adapter_packet: 'verification/worker/adapter/1/packet.json',
    bundle: { run_id: runId, base_commit: BASE_COMMIT, candidate_commit: CANDIDATE_COMMIT, policy_sha256: 'e'.repeat(64) },
  })
  const launchEvents = (time: string) => [
    internalEvent(1, time, 'ui', 'running', 'Launching or reconciling the exact native session'),
    internalEvent(2, time, 'adapter', 'running', 'Launching or reconciling the exact native session'),
  ]

  writeRun(runsRoot, repository, RUN_SUCCEEDED, {
    createdAt: T0, updatedAt: T3, definitionNodes: PINNED_NODES,
    values: {
      ...reviewedValues(RUN_SUCCEEDED, T0),
      review: { run_id: RUN_SUCCEEDED, verdict: 'approved', independent: true, reviewer: 'synthetic-reviewer', findings: [] },
      approved_bundle: 'f'.repeat(64), integrated_commit: CANDIDATE_COMMIT,
    },
    next: [], tasks: [],
    events: [
      ...launchEvents(T0),
      internalEvent(3, T1, 'freeze', 'succeeded', 'Captured both worker snapshots'),
      internalEvent(4, T2, 'verify_ui', 'succeeded', 'UI verification passed'),
      internalEvent(5, T2, 'verify_adapter', 'succeeded', 'Adapter verification passed'),
      internalEvent(6, T3, 'review', 'approved', 'Independent reviewer approved the candidate'),
      internalEvent(7, T3, 'integrate', 'succeeded', 'Fast-forwarded the feature branch'),
    ],
    packets: runDir => fullPackets(RUN_SUCCEEDED, runDir),
    review: rawReviewSection(RUN_SUCCEEDED, leakFor(runsRoot, RUN_SUCCEEDED)),
    inputs: rawInputsSection(RUN_SUCCEEDED, leakFor(runsRoot, RUN_SUCCEEDED)),
    diff: REVIEW_DIFF,
  })

  writeRun(runsRoot, repository, RUN_FAILED, {
    createdAt: T1, updatedAt: T2, definitionNodes: GRAPH_NODES,
    values: {
      ui: receipt('ui', join(runsRoot, RUN_FAILED), UI_SESSION, T1), adapter: receipt('adapter', join(runsRoot, RUN_FAILED), ADAPTER_SESSION, T1),
      snapshots: { ui: OUTPUT_COMMIT_UI, adapter: OUTPUT_COMMIT_ADAPTER },
      ui_packet: 'verification/worker/ui/1/packet.json',
    },
    next: ['verify_adapter'],
    tasks: [{ node_id: 'verify_adapter', error: 'Injected gate failure: adapter verification attempt 1 was blocked by the configured failure drill', interrupts: [], result: null }],
    events: [
      ...launchEvents(T1),
      internalEvent(3, T2, 'freeze', 'succeeded', 'Captured both worker snapshots'),
      internalEvent(4, T2, 'verify_ui', 'succeeded', 'UI verification passed'),
      internalEvent(5, T2, 'verify_adapter', 'failed', 'Injected gate failure (failure drill); checks preserved'),
    ],
    packets: runDir => packetSet(runDir, [
      { phase: 'worker', node: 'ui', attempt: 1, result: uiResult(RUN_FAILED) },
      { phase: 'worker', node: 'adapter', attempt: 1, result: adapterResult(RUN_FAILED, true), blocked: 'Injected gate failure (failure drill)' },
    ]),
    review: null,
    inputs: rawInputsSection(RUN_FAILED, leakFor(runsRoot, RUN_FAILED)),
  })

  writeRun(runsRoot, repository, RUN_AWAITING, {
    createdAt: T2, updatedAt: T3, definitionNodes: GRAPH_NODES,
    values: reviewedValues(RUN_AWAITING, T2),
    next: ['review'],
    tasks: [{ node_id: 'review', error: null, interrupts: [{ kind: 'independent_review', message: 'Independent review required before integration' }], result: null }],
    events: [
      ...launchEvents(T2),
      internalEvent(3, T3, 'freeze', 'succeeded', 'Captured both worker snapshots'),
      internalEvent(4, T3, 'candidate', 'succeeded', 'Combined candidate checks passed'),
      internalEvent(5, T3, 'review', 'awaiting_approval', 'Independent review required before integration'),
    ],
    packets: runDir => fullPackets(RUN_AWAITING, runDir),
    review: null,
    inputs: rawInputsSection(RUN_AWAITING, leakFor(runsRoot, RUN_AWAITING)),
  })

  // The print-mode reviewer blocked this candidate: review.json holds the verdict, the graph task the error.
  writeRun(runsRoot, repository, RUN_BLOCKED, {
    createdAt: T1, updatedAt: T3, definitionNodes: GRAPH_NODES,
    values: reviewedValues(RUN_BLOCKED, T1),
    next: [],
    tasks: [{ node_id: 'review', error: `${BLOCKED_MESSAGE}; see ${join(runsRoot, RUN_BLOCKED, 'review.json')}`, interrupts: [], result: null }],
    events: [
      ...launchEvents(T1),
      internalEvent(3, T2, 'freeze', 'succeeded', 'Captured both worker snapshots'),
      internalEvent(4, T2, 'verify_ui', 'succeeded', 'UI verification passed'),
      internalEvent(5, T2, 'verify_adapter', 'succeeded', 'Adapter verification passed'),
      internalEvent(6, T2, 'candidate', 'succeeded', 'Combined candidate checks passed'),
      internalEvent(7, T3, 'review', 'running', 'Launching the print-mode reviewer'),
      internalEvent(8, T3, 'review', 'blocked', BLOCKED_MESSAGE),
    ],
    packets: runDir => packetSet(runDir, [
      { phase: 'worker', node: 'ui', attempt: 1, result: uiDeferredResult(RUN_BLOCKED) },
      { phase: 'worker', node: 'adapter', attempt: 1, result: adapterResult(RUN_BLOCKED, false) },
      { phase: 'candidate', node: 'ui', attempt: 1, result: uiResult(RUN_BLOCKED) },
      { phase: 'candidate', node: 'adapter', attempt: 1, result: adapterResult(RUN_BLOCKED, false) },
    ]),
    review: rawReviewSection(RUN_BLOCKED, leakFor(runsRoot, RUN_BLOCKED)),
    inputs: rawInputsSection(RUN_BLOCKED, leakFor(runsRoot, RUN_BLOCKED)),
  })

  // Integrated before review results and run inputs were exported: a 1.0.0 export whose `values.review` is never mined.
  writeRun(runsRoot, repository, RUN_LEGACY, {
    createdAt: T0, updatedAt: T2, definitionNodes: GRAPH_NODES,
    values: {
      ...reviewedValues(RUN_LEGACY, T0),
      review: { run_id: RUN_LEGACY, verdict: 'approved', independent: true, reviewer: 'synthetic-reviewer', findings: [] },
      approved_bundle: 'f'.repeat(64), integrated_commit: CANDIDATE_COMMIT,
    },
    next: [], tasks: [],
    events: [
      ...launchEvents(T0),
      internalEvent(3, T1, 'freeze', 'succeeded', 'Captured both worker snapshots'),
      internalEvent(4, T1, 'verify_ui', 'succeeded', 'UI verification passed'),
      internalEvent(5, T1, 'verify_adapter', 'succeeded', 'Adapter verification passed'),
      internalEvent(6, T2, 'review', 'approved', 'Review accepted (recorded before review results were exported)'),
      internalEvent(7, T2, 'integrate', 'succeeded', 'Fast-forwarded the feature branch'),
    ],
    packets: runDir => fullPackets(RUN_LEGACY, runDir),
    version: '1.0.0',
  })

  // ---- lanes-flow: 1.3.0 exports of runs whose lanes come from configuration (`ui`, `adapter`, `docs`) ----

  /** Per-lane state as the plan-driven pipeline keeps it, up to the verified candidate: receipts under `lanes`, packet paths under `packets`. */
  const laneCandidateValues = (runsRoot: string, runId: string, lanes: readonly string[], requestedAt: string) => ({
    lanes: Object.fromEntries(lanes.map(lane => [lane, receipt(lane, join(runsRoot, runId), LANE_SESSIONS[lane], requestedAt)])),
    snapshots: Object.fromEntries(lanes.map(lane => [lane, LANE_OUTPUT_COMMITS[lane]])),
    packets: Object.fromEntries(lanes.map(lane => [lane, `verification/worker/${lane}/1/packet.json`])),
    bundle: { run_id: runId, base_commit: BASE_COMMIT, candidate_commit: CANDIDATE_COMMIT, policy_sha256: 'e'.repeat(64) },
  })
  /** A configured run that was reviewed, approved and integrated. */
  const laneValues = (runId: string, lanes: readonly string[], requestedAt: string, runsRoot = lanesRunsRoot) => ({
    ...laneCandidateValues(runsRoot, runId, lanes, requestedAt),
    review: { run_id: runId, verdict: 'approved', independent: true, reviewer: 'synthetic-reviewer', findings: [] },
    approved_bundle: 'f'.repeat(64), integrated_commit: CANDIDATE_COMMIT,
  })
  const lanePackets = (runId: string, runDir: string, lanes: readonly string[]) => packetSet(runDir, lanes.flatMap(lane => [
    { phase: 'worker' as const, node: lane, attempt: 1, result: laneResult(lane, runId) },
    { phase: 'candidate' as const, node: lane, attempt: 1, result: laneResult(lane, runId) },
  ]))
  const laneEvents = (lanes: readonly string[], start: string, extra: InternalEvent[] = []): InternalEvent[] => {
    const events: InternalEvent[] = []
    const push = (time: string, node: string, status: string, message: string) => events.push(internalEvent(events.length + 1, time, node, status, message))
    for (const lane of lanes) push(start, lane, 'running', 'Launching or reconciling the exact native session')
    for (const event of extra) push(event.time, event.node, event.status, event.message)
    push(T2, 'freeze', 'succeeded', `Captured ${lanes.length === 1 ? 'the' : 'every'} worker snapshot`)
    for (const lane of lanes) push(T2, `verify_${lane}`, 'succeeded', `${lane} verification passed`)
    push(T2, 'candidate', 'succeeded', 'Combined candidate checks passed')
    push(T3, 'review', 'approved', 'Independent reviewer approved the candidate')
    push(T3, 'integrate', 'succeeded', 'Fast-forwarded the feature branch')
    return events
  }

  writeRun(lanesRunsRoot, repository, RUN_THREE_LANES, {
    createdAt: T1, updatedAt: T3, definitionNodes: THREE_LANE_NODES, definitionName: LANES_WORKFLOW_NAME, version: '1.3.0', lanes: THREE_LANES,
    values: laneValues(RUN_THREE_LANES, THREE_LANES, T1),
    next: [], tasks: [],
    events: laneEvents(THREE_LANES, T1),
    packets: runDir => lanePackets(RUN_THREE_LANES, runDir, THREE_LANES),
    review: rawReviewSection(RUN_THREE_LANES, leakFor(lanesRunsRoot, RUN_THREE_LANES)),
    inputs: rawInputsSection(RUN_THREE_LANES, leakFor(lanesRunsRoot, RUN_THREE_LANES)),
  })

  // Launched with `--workers docs`: the plan pins one lane and excludes the other two; the drill's lane was not selected.
  writeRun(lanesRunsRoot, repository, RUN_ONE_LANE, {
    createdAt: T2, updatedAt: T3, definitionNodes: ONE_LANE_NODES, definitionName: LANES_WORKFLOW_NAME, version: '1.3.0', lanes: ONE_LANE,
    values: laneValues(RUN_ONE_LANE, ONE_LANE, T2),
    next: [], tasks: [],
    events: laneEvents(ONE_LANE, T2, [internalEvent(0, T2, 'failure_drill', 'skipped', 'Failure drill skipped: its lane adapter was not selected')]),
    packets: runDir => lanePackets(RUN_ONE_LANE, runDir, ONE_LANE),
    review: rawReviewSection(RUN_ONE_LANE, leakFor(lanesRunsRoot, RUN_ONE_LANE)),
    inputs: rawInputsSection(RUN_ONE_LANE, leakFor(lanesRunsRoot, RUN_ONE_LANE)),
  })

  // ---- reviewers-flow: a feature declaring the reviewers `general` and `coverage` over the plain two-lane graph ----

  const reviewersLeak = (runId: string) => leakFor(reviewersRunsRoot, runId)
  const reviewerLaunchEvents = (): InternalEvent[] => [
    internalEvent(0, T2, 'review', 'running', 'Launching reviewer general over the shared review worktree'),
    internalEvent(0, T2, 'review', 'running', 'Launching reviewer coverage over the shared review worktree'),
  ]

  // Both reviewers' completion files were accepted: review.json holds the combined verdict and both entries.
  writeRun(reviewersRunsRoot, repository, RUN_TWO_REVIEWERS, {
    createdAt: T1, updatedAt: T3, definitionNodes: REVIEWERS_NODES, definitionName: REVIEWERS_WORKFLOW_NAME, version: '1.4.0', lanes: TWO_LANES, reviewers: TWO_REVIEWERS,
    values: {
      ...laneValues(RUN_TWO_REVIEWERS, TWO_LANES, T1, reviewersRunsRoot),
      review: {
        run_id: RUN_TWO_REVIEWERS, verdict: 'approved', independent: true, reviewer: 'synthetic-reviewer', findings: [],
        reviewers: TWO_REVIEWERS.map(reviewer => ({ reviewer_id: reviewer, session_id: `synthetic-${reviewer}`, verdict: 'approved', accepted_at: T3 })),
      },
    },
    next: [], tasks: [],
    events: laneEvents(TWO_LANES, T1, reviewerLaunchEvents()),
    packets: runDir => lanePackets(RUN_TWO_REVIEWERS, runDir, TWO_LANES),
    review: rawReviewSection(RUN_TWO_REVIEWERS, reviewersLeak(RUN_TWO_REVIEWERS)),
    inputs: rawInputsSection(RUN_TWO_REVIEWERS, reviewersLeak(RUN_TWO_REVIEWERS)),
  })

  // `coverage` blocked while `general` was still working: the run failed at the review node and `general` was stopped and superseded.
  writeRun(reviewersRunsRoot, repository, RUN_REVIEWER_BLOCKED, {
    createdAt: T2, updatedAt: T3, definitionNodes: REVIEWERS_NODES, definitionName: REVIEWERS_WORKFLOW_NAME, version: '1.4.0', lanes: TWO_LANES, reviewers: TWO_REVIEWERS,
    values: laneCandidateValues(reviewersRunsRoot, RUN_REVIEWER_BLOCKED, TWO_LANES, T2),
    next: [],
    tasks: [{ node_id: 'review', error: `${REVIEWER_BLOCKED_MESSAGE}; see ${join(reviewersRunsRoot, RUN_REVIEWER_BLOCKED, 'review.json')}`, interrupts: [], result: null }],
    events: (() => {
      const events: InternalEvent[] = []
      const push = (time: string, node: string, status: string, message: string) => events.push(internalEvent(events.length + 1, time, node, status, message))
      for (const lane of TWO_LANES) push(T2, lane, 'running', 'Launching or reconciling the exact native session')
      push(T2, 'freeze', 'succeeded', 'Captured every worker snapshot')
      for (const lane of TWO_LANES) push(T2, `verify_${lane}`, 'succeeded', `${lane} verification passed`)
      push(T2, 'candidate', 'succeeded', 'Combined candidate checks passed')
      for (const event of reviewerLaunchEvents()) push(event.time, event.node, event.status, event.message)
      push(T3, 'review', 'blocked', REVIEWER_BLOCKED_MESSAGE)
      return events
    })(),
    packets: runDir => lanePackets(RUN_REVIEWER_BLOCKED, runDir, TWO_LANES),
    review: rawReviewSection(RUN_REVIEWER_BLOCKED, reviewersLeak(RUN_REVIEWER_BLOCKED)),
    inputs: rawInputsSection(RUN_REVIEWER_BLOCKED, reviewersLeak(RUN_REVIEWER_BLOCKED)),
  })

  // Reviewed before the feature declared reviewers: a 1.3.0 export whose review section has no `reviewers` list.
  writeRun(reviewersRunsRoot, repository, RUN_LEGACY_REVIEWER, {
    createdAt: T0, updatedAt: T2, definitionNodes: REVIEWERS_NODES, definitionName: REVIEWERS_WORKFLOW_NAME, version: '1.3.0', lanes: TWO_LANES,
    values: laneValues(RUN_LEGACY_REVIEWER, TWO_LANES, T0, reviewersRunsRoot),
    next: [], tasks: [],
    events: laneEvents(TWO_LANES, T0),
    packets: runDir => lanePackets(RUN_LEGACY_REVIEWER, runDir, TWO_LANES),
    review: rawReviewSection(RUN_LEGACY_REVIEWER, reviewersLeak(RUN_LEGACY_REVIEWER)),
    inputs: rawInputsSection(RUN_LEGACY_REVIEWER, reviewersLeak(RUN_LEGACY_REVIEWER)),
  })

  // ---- clarity-flow: the ui worker-phase packet captured the changed files at freeze (PRD_VIEWER_CLARITY 4.1) ----

  writeRun(clarityRunsRoot, repository, RUN_FILES, {
    createdAt: T1, updatedAt: T3, definitionNodes: CLARITY_NODES, definitionName: CLARITY_WORKFLOW_NAME, version: '1.4.0', lanes: TWO_LANES, reviewers: TWO_REVIEWERS,
    values: laneValues(RUN_FILES, TWO_LANES, T1, clarityRunsRoot),
    next: [], tasks: [],
    events: laneEvents(TWO_LANES, T1, reviewerLaunchEvents()),
    packets: runDir => [
      writePacket(runDir, 'worker', 'ui', 1, capturedUiResult(RUN_FILES), [...LANE_ARTIFACTS.ui, ...FILE_ARTIFACTS], { status: 'passed', reasons: [] }),
      writePacket(runDir, 'worker', 'adapter', 1, adapterResult(RUN_FILES, false), LANE_ARTIFACTS.adapter, { status: 'passed', reasons: [] }),
      writePacket(runDir, 'candidate', 'ui', 1, candidateUiResult(RUN_FILES), LANE_ARTIFACTS.ui, { status: 'passed', reasons: [] }),
      writePacket(runDir, 'candidate', 'adapter', 1, adapterResult(RUN_FILES, false), LANE_ARTIFACTS.adapter, { status: 'passed', reasons: [] }),
    ],
    review: rawReviewSection(RUN_FILES, leakFor(clarityRunsRoot, RUN_FILES)),
    inputs: rawInputsSection(RUN_FILES, leakFor(clarityRunsRoot, RUN_FILES)),
  })

  // ---- guarded-flow: 1.5.0 exports whose graph starts with the design challenge (PRD_PORTABLE_WORKFLOW 4.5 to 4.7) ----

  // Finished: the challenge was accepted at attempt 2, both lanes verified (ui captured a Markdown file), the print reviewer
  // approved at attempt 1 with a finding naming that file, and the candidate was integrated.
  writeRun(guardedRunsRoot, repository, RUN_GUARDED, {
    createdAt: T1, updatedAt: T3, definitionNodes: GUARDED_NODES, definitionName: GUARDED_WORKFLOW_NAME, version: '1.5.0', lanes: TWO_LANES,
    values: laneValues(RUN_GUARDED, TWO_LANES, T1, guardedRunsRoot),
    next: [], tasks: [],
    events: [
      internalEvent(1, T1, 'challenge', 'succeeded', `Design challenge attempt 2 accepted by the operator: ${CHALLENGE_ACCEPTED_REASON}`),
      internalEvent(2, T1, 'ui', 'running', 'Launching or reconciling the exact native session'),
      internalEvent(3, T1, 'adapter', 'running', 'Launching or reconciling the exact native session'),
      internalEvent(4, T2, 'freeze', 'succeeded', 'Captured every worker snapshot'),
      internalEvent(5, T2, 'verify_ui', 'succeeded', 'ui verification passed; changed text files captured at freeze'),
      internalEvent(6, T2, 'verify_adapter', 'succeeded', 'adapter verification passed'),
      internalEvent(7, T2, 'candidate', 'succeeded', 'Combined candidate checks passed'),
      internalEvent(8, T3, 'review', 'approved', 'Independent reviewer approved the candidate'),
      internalEvent(9, T3, 'integrate', 'succeeded', 'Fast-forwarded the feature branch'),
    ],
    packets: runDir => [
      writePacket(runDir, 'worker', 'ui', 1, guardedUiResult(RUN_GUARDED), [...LANE_ARTIFACTS.ui, ...GUARDED_FILE_ARTIFACTS], { status: 'passed', reasons: [] }),
      writePacket(runDir, 'worker', 'adapter', 1, adapterResult(RUN_GUARDED, false), LANE_ARTIFACTS.adapter, { status: 'passed', reasons: [] }),
      writePacket(runDir, 'candidate', 'ui', 1, uiResult(RUN_GUARDED), LANE_ARTIFACTS.ui, { status: 'passed', reasons: [] }),
      writePacket(runDir, 'candidate', 'adapter', 1, adapterResult(RUN_GUARDED, false), LANE_ARTIFACTS.adapter, { status: 'passed', reasons: [] }),
    ],
    review: rawReviewSection(RUN_GUARDED, leakFor(guardedRunsRoot, RUN_GUARDED)),
    inputs: rawInputsSection(RUN_GUARDED, leakFor(guardedRunsRoot, RUN_GUARDED)),
  })

  /** Both sessions launched and the automatic run waits at the handoff interrupt: nothing is frozen or verified yet. */
  const awaitingHandoffs = (runId: string) => ({
    values: { lanes: Object.fromEntries(TWO_LANES.map(lane => [lane, receipt(lane, join(guardedRunsRoot, runId), LANE_SESSIONS[lane], T1)])) },
    next: ['handoff'],
    tasks: [{ node_id: 'handoff', error: null, interrupts: [{ kind: 'worker_handoff', message: 'Awaiting explicit completion signals and automatic freeze.' }], result: null }],
  })
  const guardedLaunchEvents = [
    internalEvent(1, T1, 'challenge', 'succeeded', 'Design challenge attempt 1 passed (1 P2 concern(s)); launching workers'),
    internalEvent(2, T1, 'ui', 'running', 'Launching or reconciling the exact native session'),
    internalEvent(3, T1, 'adapter', 'running', 'Launching or reconciling the exact native session'),
  ]

  // Waiting on handoffs: ui finished its turn; the adapter's second question waits on the operator (its file was moved).
  const askingDir = join(guardedRunsRoot, RUN_GUARDED_ASKING)
  writeRun(guardedRunsRoot, repository, RUN_GUARDED_ASKING, {
    createdAt: T1, updatedAt: T3, definitionNodes: GUARDED_NODES, definitionName: GUARDED_WORKFLOW_NAME, version: '1.5.0', lanes: TWO_LANES,
    ...awaitingHandoffs(RUN_GUARDED_ASKING),
    events: [
      ...guardedLaunchEvents,
      internalEvent(4, T2, 'adapter', 'interactive', `Worker adapter asked question 1 of 3; its deadline is paused until \`python -m workflow answer ${askingDir} adapter "<text>"\`: ${GUARDED_QUESTIONS.adapter[0].question}`),
      internalEvent(5, T2, 'adapter', 'interactive', 'Worker adapter question 1 answered; its deadline runs again'),
      internalEvent(6, T3, 'adapter', 'interactive', `Worker adapter asked question 2 of 3; its deadline is paused until \`python -m workflow answer ${askingDir} adapter "<text>"\`: ${GUARDED_QUESTIONS.adapter[1].question}`),
    ],
    packets: () => [],
    review: null,
    inputs: rawInputsSection(RUN_GUARDED_ASKING, leakFor(guardedRunsRoot, RUN_GUARDED_ASKING)),
  })

  // Blocked in the same wait: the ui worker asked a fourth question, which the controller refused, and it stopped both workers.
  writeRun(guardedRunsRoot, repository, RUN_GUARDED_BLOCKED, {
    createdAt: T1, updatedAt: T3, definitionNodes: GUARDED_NODES, definitionName: GUARDED_WORKFLOW_NAME, version: '1.5.0', lanes: TWO_LANES,
    ...awaitingHandoffs(RUN_GUARDED_BLOCKED),
    events: [
      ...guardedLaunchEvents,
      internalEvent(4, T2, 'ui', 'interactive', 'Worker ui question 3 answered; its deadline runs again'),
      internalEvent(5, T3, 'controller', 'blocked', FOURTH_QUESTION_MESSAGE),
    ],
    packets: () => [],
    review: null,
    inputs: rawInputsSection(RUN_GUARDED_BLOCKED, leakFor(guardedRunsRoot, RUN_GUARDED_BLOCKED)),
  })

  // ---- viewer UX slices: each module seeds its own workflow, appended after every workflow above ----

  const ux = seedUxFixtures({
    repository,
    runsRoot: workflowId => {
      const directory = join(root, 'runs', workflowId)
      mkdirSync(directory, { recursive: true })
      return directory
    },
    writeRun, writePacket, receipt, internalEvent, leakFor,
  })

  const registry = {
    version: 1,
    ...ux.registry,
    projects: [
      {
        project_id: PROJECT.project_id, name: PROJECT.name, repository,
        workflows: [
          { workflow_id: WORKFLOW_ID, runs_root: runsRoot, definition: { name: WORKFLOW_NAME, nodes: GRAPH_NODES } },
          { workflow_id: EMPTY_WORKFLOW_ID, runs_root: emptyRunsRoot, definition: { name: EMPTY_WORKFLOW_NAME, nodes: EMPTY_WORKFLOW_DEFINITION.nodes } },
          { workflow_id: LANES_WORKFLOW_ID, runs_root: lanesRunsRoot, definition: { name: LANES_WORKFLOW_NAME, nodes: THREE_LANE_NODES } },
          { workflow_id: REVIEWERS_WORKFLOW_ID, runs_root: reviewersRunsRoot, definition: { name: REVIEWERS_WORKFLOW_NAME, nodes: REVIEWERS_NODES } },
          { workflow_id: CLARITY_WORKFLOW_ID, runs_root: clarityRunsRoot, definition: { name: CLARITY_WORKFLOW_NAME, nodes: CLARITY_NODES } },
          { workflow_id: GUARDED_WORKFLOW_ID, runs_root: guardedRunsRoot, definition: { name: GUARDED_WORKFLOW_NAME, nodes: GUARDED_NODES } },
          ...ux.workflows,
        ],
      },
      { project_id: EMPTY_PROJECT.project_id, name: EMPTY_PROJECT.name, repository, workflows: [] },
    ],
  }
  const configPath = join(root, 'projects.json')
  writeJson(configPath, registry)
  return configPath
}

