  session_id: z.string().min(1).nullable(),
  verdict: z.enum(['approved', 'blocked']).nullable(),
  findings: z.array(reviewFindingSectionSchema),
  launched_at: zonedTimestamp.nullable(),
  accepted_at: zonedTimestamp.nullable(),
