  if (referenceTime === null && dayNumber(against) - dayNumber(parts) === 1) return `yesterday ${clock}`
  return `${MONTHS[parts.month]} ${parts.day}${parts.year === against.year ? '' : ` ${parts.year}`} ${clock}`
