/* ---- Review section (docs/PRD_VIEWER_UX.md 4.7); the review panel's own rules stay in App.css until S4c moves them. ---- */

.node-section .review-result { margin-top: 0; }

/* What blocks integration: one card per unresolved P0/P1, before the findings table. */
.blocking-cards { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.blocking-card {
  border: 1px solid var(--border);
  border-left: 4px solid var(--danger-text);
  border-radius: 6px;
  padding: 8px 12px;
  min-width: 0;
}
.blocking-card p { margin: 0; overflow-wrap: anywhere; }
.blocking-card-head { font-size: 0.85rem; }
.blocking-card-head .finding-severity { color: var(--danger-text); }
.blocking-card-message { margin-top: 4px !important; font-weight: 600; }
.blocking-card-links { margin-top: 6px !important; display: flex; flex-wrap: wrap; gap: 4px 16px; font-size: 0.85rem; }

/* A reviewer's time beside its outcome: from served fields only. */
.reviewer-time { font-variant-numeric: tabular-nums; }

/* At 760 px and below the same findings table reads as cards: one block per finding, each cell labelled, no sideways scroll. */
@media (max-width: 760px) {
  .node-section .findings-table { min-width: 0; border-collapse: separate; border-spacing: 0; }
  .node-section .findings-table thead {
    position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
  }
  .node-section .findings-table,
  .node-section .findings-table tbody,
  .node-section .findings-table tr,
  .node-section .findings-table td { display: block; width: 100%; box-sizing: border-box; }
  .node-section .findings-table tr { border: 1px solid var(--border); border-radius: 6px; margin-bottom: 8px; padding: 6px 8px; }
  .node-section .findings-table tr.finding-blocking { border-left: 4px solid var(--danger-text); }
  .node-section .findings-table td { border: 0; padding: 2px 0; }
  .node-section .findings-table .finding-blocking > td:first-child { border-left: 0; }
  .node-section .findings-table td[data-label]::before { content: attr(data-label) ': '; font-weight: 600; color: var(--text-muted, inherit); }
  .node-section .findings-table td[data-label="Message"]::before { content: none; }
}

